func (d *DeviceTypeListDataSource) Read(ctx context.Context, req datasource.ReadRequest, resp *datasource.ReadResponse) {
	var cfg DeviceTypeListDataSourceModel
	resp.Diagnostics.Append(req.Config.Get(ctx, &cfg)...)
	if resp.Diagnostics.HasError() {
		return
	}
	query := url.Values{}
	conv.ApplyFilters(ctx, cfg.Filters, deviceTypeFilterNames, query, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	limit := int64(-1)
	if conv.Known(cfg.Limit) {
		limit = cfg.Limit.ValueInt64()
	}
	pageSize := int64(netbox.DefaultPageSize)
	if limit >= 0 && limit < pageSize {
		pageSize = limit
	}
	var objs []netbox.DeviceType
	offset := int64(0)
	for limit != 0 {
		query.Set("limit", strconv.FormatInt(pageSize, 10))
		query.Set("offset", strconv.FormatInt(offset, 10))
		var page netbox.PaginatedDeviceTypeList
		if err := d.client.GetRaw(ctx, "/api/dcim/device-types/?"+query.Encode(), &page); err != nil {
			resp.Diagnostics.AddError("Error listing netbox_device_types", err.Error())
			return
		}
		objs = append(objs, page.Results...)
		offset += int64(len(page.Results))
		if len(page.Results) == 0 || offset >= int64(page.GetCount()) || (limit > 0 && int64(len(objs)) >= limit) {
			break
		}
	}
	if limit > 0 && int64(len(objs)) > limit {
		objs = objs[:limit]
	}
	items := make([]DeviceTypeDataModel, 0, len(objs))
	for i := range objs {
		var m DeviceTypeDataModel
		deviceTypeDataFromAPI(ctx, &objs[i], &m, &resp.Diagnostics)
		items = append(items, m)
	}
	if resp.Diagnostics.HasError() {
		return
	}
	list, diags := types.ListValueFrom(ctx, types.ObjectType{AttrTypes: provider.AttrTypes(deviceTypeDataAttributes(false))}, items)
	resp.Diagnostics.Append(diags...)
	cfg.Items = list
	resp.Diagnostics.Append(resp.State.Set(ctx, &cfg)...)
}

// deviceTypeDataFromAPI copies an API object into the model.
