	_ = ctx
	out.Id = types.Int64Value(int64(obj.GetId()))
	out.ManufacturerId = conv.BriefID(obj.GetManufacturerOk())
	out.DefaultPlatformId = conv.BriefID(obj.GetDefaultPlatformOk())
	out.Model = conv.String(obj.GetModelOk())
